contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address logAddr, uint val) public payable {
        require(logAddr != address(0));
        bool firstInitReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstInitReverted = true;
        } else {
            firstInitReverted = false;
        }
        bool secondInitReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondInitReverted = true;
        } else {
            secondInitReverted = false;
        }
        bool setLogReverted;
        c.SetLogFile(logAddr); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            setLogReverted = true;
        } else {
            setLogReverted = false;
        }
        assert(!firstInitReverted && !secondInitReverted && setLogReverted);
    }
}

