pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address logAddr, uint256 val) internal {
        vm.assume(logAddr != address(0));
        bool firstInitReverted;
        try c.Initialized() {
            firstInitReverted = false;
        } catch {
            firstInitReverted = true;
        }
        bool secondInitReverted;
        try c.Initialized() {
            secondInitReverted = false;
        } catch {
            secondInitReverted = true;
        }
        bool setLogReverted;
        try c.SetLogFile(logAddr) {
            setLogReverted = false;
        } catch {
            setLogReverted = true;
        }
        assertTrue(!firstInitReverted && !secondInitReverted && setLogReverted);
    }

    function testFuzz_run(address logAddr, uint256 val) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(logAddr, val);
    }

    receive() external payable {}
}
